<x-app-layout><x-slot name="header"><div><h1 class="text-xl font-bold text-slate-900">Issue Add</h1><p class="mt-1 text-sm text-slate-500">Select an item number to fill item, unit, and available balance automatically.</p></div></x-slot><form method="POST" action="{{ route('inventory-issues.store') }}" x-data="issueForm()">@csrf
