<section class="mt-5 overflow-hidden rounded-xl border border-sky-200 bg-white shadow-sm"><div class="bg-sky-500 px-5 py-3 text-sm font-semibold text-white">Details</div><div class="overflow-x-auto"><table class="w-full min-w-[1050px] text-sm"><thead class="bg-sky-50 text-left"><tr><th class="p-3">#</th><th class="p-3">Item No</th><th class="p-3">Item</th><th class="p-3">Store Position</th><th class="p-3">Balance</th><th class="p-3">Unit</th><th class="p-3">Qty</th><th class="p-3">ChesisNo</th><th></th></tr></thead><tbody><template x-for="(line,index) in lines" :key="index"><tr class="border-t"><td class="p-3" x-text="index+1"></td><td class="p-2"><input x-model="line.partNo" @input="match(line)" :list="`issue-items-${index}`" placeholder="Item no" class="w-full rounded border-slate-300"><datalist :id="`issue-items-${index}`"><template x-for="p in products" :key="p.id"><option :value="p.part_no" x-text="`${p.part_no} — ${p.name}`"></option></template></datalist><input type="hidden" :name="`items[${index}][product_id]`" x-model="line.productId"></td><td class="p-2"><input x-model="line.name" readonly class="w-full rounded border-slate-200 bg-slate-50"></td><td class="p-2"><select x-model="line.positionId" :name="`items[${index}][store_position_id]`" class="w-full rounded border-slate-300"><option value="">[Select]</option><template x-for="position in positions.filter(p=>String(p.store_id)===String(storeId))" :key="position.id"><option :value="position.id" x-text="position.name"></option></template></select></td><td class="p-2"><input x-model="line.balance" :name="`items[${index}][balance_quantity]`" readonly class="w-full rounded border-slate-200 bg-slate-50"></td><td class="p-2"><input x-model="line.unit" readonly class="w-full rounded border-slate-200 bg-slate-50"></td><td class="p-2"><input x-model.number="line.qty" :name="`items[${index}][quantity]`" type="number" min=".01" step=".01" class="w-full rounded border-slate-300"></td><td class="p-2"><input :name="`items[${index}][chassis_no]`" x-model="line.chassis" class="w-full rounded border-slate-300"></td><td class="p-2"><button type="button" @click="remove(index)" x-show="lines.length>1" class="text-rose-600">Remove</button></td></tr></template></tbody></table></div><button type="button" @click="add" class="m-4 rounded bg-sky-100 px-3 py-2 text-sm font-semibold text-sky-800">+ Add row</button></section><div class="mt-6 flex gap-3"><button class="rounded bg-[#1f7d88] px-5 py-2.5 text-sm font-semibold text-white">Save</button><a href="{{ route('inventory-issues.index') }}" class="crm-cancel-button rounded px-5 py-2.5 text-sm">Cancel</a></div></form>
<script>function issueForm(){return{products:@json($products),positions:@json($positions),storeId:'',lines:[{partNo:'',productId:'',name:'',positionId:'',balance:0,unit:'',qty:0,chassis:''}],add(){this.lines.push({partNo:'',productId:'',name:'',positionId:'',balance:0,unit:'',qty:0,chassis:''})},remove(i){this.lines.splice(i,1)},match(line){let q=line.partNo.toLowerCase();let p=this.products.find(x=>x.part_no?.toLowerCase()===q||`${x.part_no} — ${x.name}`.toLowerCase()===q);if(p){Object.assign(line,{partNo:p.part_no,productId:p.id,name:p.name,balance:p.balance,unit:p.unit})}else Object.assign(line,{productId:'',name:'',balance:0,unit:''})}}}</script></x-app-layout>
